(()=>{'use strict';const C=window.FLIGHT_COMPLETION,el=id=>document.getElementById(id);let context=null,last=null,scheduled=false;
const legend=document.createElement('div');legend.className='completion-legend';legend.innerHTML='<span class="legend-ready">✓ Complete</span><span class="legend-attention">! Needs attention</span><span>Optional empty fields stay neutral. Green means an input/check is complete under the app’s rules, not flight clearance. Prefilled aircraft suggestions stay orange until configuration is confirmed.</span>';document.getElementById('navsections').append(legend);
const n=id=>{const v=el(id)?.value?.trim();return v===''||v===undefined?null:Number(v);},v=id=>el(id)?.value||'',pass=(ok,text)=>({pass:!!ok,text});
function semantic(id){if(id==='onsiteconditions')return pass(!!window.flightOnsiteReview?.().complete,'Record local assessment');if(id==='scopeoption')return pass(!!window.flightScopeReview?.().valid,'Supported scope required');if(id==='controllerready')return pass(el(id).checked,'Review controller');if(['cellalternativeref','cellunavailablereason','cellalternativeconfirm'].includes(id)&&context?.cellMethod==='documented')return pass(!!context?.cellAlternative,'Complete documented battery verification');if(!context)return null;const c=context,m=c.manufacturer;if(['lat','lon','postcode'].includes(id))return pass(c.site,'Confirm selected site');if(['date','takeofftime','hour','startminute'].includes(id))return pass(c.clock,'Check start time');if(id==='pilotselect')return pass(c.pilot,'Check pilot profile');if(id==='operatorselect')return pass(c.operator,'Check operator profile');
if(['classmark','mass','actualmass','camera','height','maxwind','mintemp','maxtemp'].includes(id)&&!c.spec)return pass(false,'Confirm configuration');
if(id==='specconfirm')return pass(el(id).checked,'Review aircraft profile');if(id==='category')return pass(['A1','A2','A3'].includes(v(id)),'Review category');if(id==='classmark')return pass(v(id)!=='unverified','Verify physical class');
if(id==='mass')return pass(n(id)>0&&(!m?.mtom||n(id)<=m.mtom),'Check MTOM');if(id==='actualmass')return pass(n(id)>0&&n(id)<=n('mass'),'Check take-off mass');if(id==='height')return pass(n(id)>0&&n(id)<=120,'Check height limit');if(id==='vlos')return pass(v(id)==='yes','Direct VLOS required');if(id==='a2'&&v('category')==='A2')return pass(['yes','no'].includes(v(id)),'A2 competence required');
if(id==='maxwind')return pass(n(id)>0&&(!m?.wind||n(id)<=m.wind),'Check manufacturer limit');if(id==='opwind')return pass(n(id)>0&&n(id)<=n('maxwind'),'Check wind limit');if(['mintemp','maxtemp'].includes(id))return pass(n('mintemp')!==null&&n('maxtemp')!==null&&n('mintemp')<n('maxtemp')&&(!m||((m.tmin===null||m.tmin===undefined||n('mintemp')>=m.tmin)&&(m.tmax===null||m.tmax===undefined||n('maxtemp')<=m.tmax))),'Check temperature limits');
if(id==='batteryselect')return pass(!!v(id),'Check saved battery');if(id==='batteryvariant')return pass(!!v(id)&&v(id)!=='manual'||!!c.battery,'Select matching battery');if(id==='batteryhealth')return pass(['ready','quarantine'].includes(v(id)),'Inspection required');if(id==='batteryinspection')return pass(v(id)===localDate(),'Inspect before flight');if(id==='batterysoc')return pass(n(id)>0&&n(id)<=100,'Enter current charge');if(id==='batteryunits')return pass(Number.isInteger(n(id))&&n(id)===n('requiredpacks'),'Check pack count');
if(id==='celllimit')return pass(c.criterionReady&&n(id)>0&&n(id)<=.1,'Review cell criterion');if(id==='cellreference')return pass(c.criterionReady&&!!v(id).trim(),'Adopt valid criterion');if(/^cell(low|high)\d+$/.test(id))return pass(c.cellRowsEntered?.[Number(id.match(/\d+$/)[0])],'Check paired readings');if(id==='cellconditions')return pass(el(id).checked,'Complete cell check');if(id==='celloverride')return pass(c.criterionReady,'Document adoption');
if(id==='reserve')return pass(n(id)>0&&n(id)<100,'Check landing charge');if(id==='endurance')return pass(n(id)>0,'Enter supported time');if(id==='contingency')return pass(n(id)!==null&&n(id)>=0,'Enter margin or zero');if(id==='batteryconfirm')return pass(el(id).checked,'Finish battery checks');
if(id==='weatherriskack')return pass(el(id).checked,'Acknowledge forecast exceedances');if(id==='weatherack')return pass(el(id).checked,'Review flight weather');if(id==='notammanual')return pass(!!window.flightAirspaceReview?.().manualNotam?.reviewComplete,'Record current official briefing');if(id==='airspacereviewed')return pass(el(id).checked,'Finish airspace review');if(id==='finalconfirm')return pass(el(id).checked,'Resolve outstanding items');if(id==='check0')return pass(c.pilot&&c.operator&&c.aircraft,'Complete aircraft/crew');if(id==='check1')return pass(c.airspace,'Complete airspace review');if(id==='check7')return pass(c.weather,'Review flight weather');if(id==='check8')return pass(c.battery&&c.cells&&c.batteryBudget&&el('batteryconfirm').checked,'Complete aircraft/battery');return null;}
function required(input,label){const id=input.id;if(context?.cellMethod==='documented'&&(['celllimit','cellreference','celloverride','celloverridereason','cellconditions'].includes(id)||/^cell(low|high)/.test(id)))return false;if(['cellalternativeref','cellunavailablereason','cellalternativeconfirm'].includes(id))return context?.cellMethod==='documented';const text=label.querySelector('.requirementlabel')?.textContent||'';if(['celllimit','cellreference'].includes(id))return true;if(id==='notamterrainref')return !!v('notamterrain').trim();if(['onsiteconditions','controllerready'].includes(id))return true;if(id==='a2')return v('category')==='A2';if(id==='notammanual')return !window.flightNotamAutomatedUsable?.();if(id==='limitref')return !!context?.manualReferenceNeeded;if(['vlosdistance','vlosbasis','vloslimitconfirm'].includes(id))return el('vloslimituse').checked;if(id==='weatherriskack')return !!context?.weatherRisk;if(id==='celloverridereason')return el('celloverride').checked;if(id==='celloverride')return !context?.criterionKnown;if(['lat','lon','postcode'].includes(id))return !context?.site||id!=='postcode';return /^(GO\/NO-GO required|Site required|Required to save|Required for recommendation)/.test(text)||input.required;}
function render(){scheduled=false;const entries=[];for(const input of document.querySelectorAll('input,select,textarea')){if(input.hidden||input.closest('.derived-check,#recent-radar-panel')||!input.id||['hidden','file','search','password','button','submit'].includes(input.type)||input.closest('.weathermap-panel,#inventory,#savedflightview,#flightcard,#postflightcard,.record-manager')||['savedflightselect','savedflightselectbottom','wxlayer','radarframe','crewkind'].includes(input.id))continue;const label=input.closest('label')||document.querySelector('label[for="'+input.id+'"]');if(!label)continue;const editor=input.closest('#profileeditor,#batteryeditor'),active=!editor||editor.open;let needed=active&&required(input,label);if(!active){label.classList.remove('entry-complete','entry-attention');input.classList.remove('input-complete','input-attention');label.querySelector('.entry-feedback')?.remove();continue;}
const status=C.status({required:needed,type:input.type,value:input.value,checked:input.checked,valid:input.validity?.valid!==false,semantic:semantic(input.id)});label.classList.toggle('entry-complete',status.state==='complete');label.classList.toggle('entry-attention',status.state==='attention');input.classList.toggle('input-complete',status.state==='complete');input.classList.toggle('input-attention',status.state==='attention');input.dataset.completion=status.state;
let feedback=label.querySelector('.entry-feedback');if(status.state==='neutral'){feedback?.remove();}else{if(!feedback){feedback=document.createElement('small');feedback.className='entry-feedback';feedback.id='entry-status-'+input.id;label.append(feedback);const ids=new Set((input.getAttribute('aria-describedby')||'').split(/\s+/).filter(Boolean));ids.add(feedback.id);input.setAttribute('aria-describedby',[...ids].join(' '));}feedback.textContent=(status.state==='complete'?'✓ ':'! ')+status.text;}
entries.push({input,needed,status});}
for(const section of document.querySelectorAll('.field-section')){const id=section.dataset.field;if(['audit','flightcard','postflightcard'].includes(id))continue;
const rows=entries.filter(r=>r.input.closest('.field-section')===section&&r.needed),additional=id==='batterycard'?[...(context?.batteryReviewPending||[])]:[];
if(id==='evidencecard')for(const [i,target]of [[0,'crewcard'],[1,'airspacecard'],[4,'aircraftcard'],[7,'weathercard'],[8,'batterycard']])if(!el('check'+i).checked)additional.push({id:'summary'+i,field:target,message:'Complete '+({0:'crew and aircraft eligibility',1:'airspace and official briefing',4:'height and VLOS',7:'weather review',8:'aircraft and battery checks'})[i]+'.'});
const risk=context?.risks?.[({weathercard:'weather',batterycard:'battery',airspacecard:'airspace',aircraftcard:'aircraft'})[id]]||'clear';
const state=id==='weathercard'&&context?.weatherAssessment?context.weatherAssessment:window.FLIGHT_ASSESSMENT.section({rows:rows.map(r=>({id:r.input.id,required:true,state:r.status.state,label:(r.input.closest('label')?.querySelector('.label')?.textContent||r.input.closest('label')?.textContent?.split('Required for recommendation')[0]?.trim()||r.status.text||'Complete required check').trim()})),additional,risk});
const ready=state.complete,summary=section.querySelector(':scope > summary');let badge=summary.querySelector('.section-completion');if(!badge){badge=document.createElement('small');badge.className='section-completion';summary.append(badge);}badge.textContent=ready?'✓ Complete':'! '+state.pending.length+' item(s) need attention';section.classList.toggle('section-complete',ready);section.classList.toggle('section-attention',!ready);section.classList.toggle('section-warning',state.risk==='caution');section.dataset.risk=state.risk||'clear';
let riskBadge=summary.querySelector('.section-risk');if(!riskBadge){riskBadge=document.createElement('small');riskBadge.className='section-risk';summary.append(riskBadge);}riskBadge.hidden=!state.risk||state.risk==='clear';riskBadge.textContent=state.risk==='unsuitable'?'Conditions unsuitable':state.risk==='caution'?'Fly with caution':'';
let outstanding=id==='weathercard'?el('weathercompletionstatus'):section.querySelector(':scope > .section-outstanding');if(!outstanding){outstanding=document.createElement('div');outstanding.className='section-outstanding';summary.after(outstanding);}outstanding.replaceChildren();outstanding.hidden=ready&&!state.riskReasons?.length;if(!ready){const title=document.createElement('strong');title.textContent='To complete this review:';const ul=document.createElement('ul');for(const item of state.pending){const li=document.createElement('li'),a=document.createElement('a');a.href='#'+item.field;a.textContent=item.message;li.append(a);ul.append(li);}outstanding.append(title,ul);}if(state.riskReasons?.length){const p=document.createElement('p');p.className='risk-explanation';p.textContent='Review recorded; operational blocker: '+state.riskReasons.join(' ');outstanding.append(p);}
}
for(const[id,ready]of [['durationresult',context?.batteryBudget],['weatherstatus',context?.weather],['cellresulttext',context?.cells]]){const box=el(id);if(box){box.classList.toggle('status-complete',!!ready);box.classList.toggle('status-attention',!ready);}}}
function schedule(){if(scheduled)return;scheduled=true;requestAnimationFrame(render);}window.addEventListener('flightdesk:decision',e=>{last=e.detail;context=last.completion;schedule();});window.addEventListener('flightdesk:planningchanged',schedule);document.addEventListener('input',schedule);document.addEventListener('change',schedule);document.addEventListener('toggle',schedule,true);document.addEventListener('click',schedule);window.updateFlightdeskDecision?.();schedule();
})();
